from collections import deque

def rolling_sums(values, width):
    if width <= 0:
        raise ValueError('width must be positive')
    recent = deque()
    total = 0
    for value in values:
        if len(recent) == width:
            total -= recent.popleft()
        recent.append(value)
        total += value
        yield total

print(list(rolling_sums(iter((2, 1, 4, 3)), 3)))
print(list(rolling_sums(iter((-2, 5)), 1)))
print(list(rolling_sums(iter(()), 2)))
try:
    print(list(rolling_sums(iter((1,)), 0)))
except ValueError:
    print('ValueError')
